1816:   const mult = run.powers.overdrive ? 2 : 1;
1817:   const value = Math.round(base * run.diff.score * run.multiplier * mult);
1818:   run.score += value;
1819:   run.stats.hits++;
1820:   if (x != null && simTime - (run.lastPop || -9) > .16) {
